with flagged as (select *, case when lag(txn_time) over (partition by merchant order by txn_time, id) is null or txn_time > lag(txn_time) over (partition by merchant order by txn_time, id) + interval 7 days then 1 else 0 end as new_group_flag from transactions), sessionized as (select *, sum(new_group_flag) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as burst_id from flagged) select id, account_id, txn_time, is_flagged, new_group_flag, burst_id from sessionized;
